191:     /// Create a time from seconds and microseconds.
192:     ///
193:     /// # Arguments
194:     ///
195:     /// * `timestamp_second` - timestamp in seconds
196:     /// * `timestamp_microsecond` - microseconds fraction of a second timestamp
197:     ///
198:     /// If `seconds + timestamp_microsecond` exceeds 86400, an error is returned.
199:     ///
200:     /// # Examples
201:     ///
202:     /// ```
203:     /// use speedate::Time;
204:     ///
205:     /// let d = Time::from_timestamp(3740, 123).unwrap();
206:     /// assert_eq!(d.to_string(), "01:02:20.000123");
207:     /// ```
208:     pub fn from_timestamp(timestamp_second: u32, timestamp_microsecond: u32) -> Result<Self, ParseError> {
209:         let mut second = timestamp_second;
210:         let mut microsecond = timestamp_microsecond;
211:         if microsecond >= 1_000_000 {
212:             second = second
213:                 .checked_add(microsecond / 1_000_000)
214:                 .ok_or(ParseError::TimeTooLarge)?;
215:             microsecond %= 1_000_000;
216:         }
217:         if second >= 86_400 {
218:             return Err(ParseError::TimeTooLarge);
219:         }
220:         Ok(Self {
221:             hour: (second / 3600) as u8,
222:             minute: ((second % 3600) / 60) as u8,
223:             second: (second % 60) as u8,
224:             microsecond,
225:             tz_offset: None,
226:         })
227:     }
